import numpy as np
from scipy.optimize import minimize
from multiprocessing import Pool, cpu_count
import sys
sys.path.append('storage/praxis')
from lp_utils import solve_radii_lp

N_CIRCLES = 32
N_PROSPECT = 1024
MAXITER_PROSPECT = 60
N_ELITE = 32
# --- CHANGE: Reduced refinement iterations to test computational cost hypothesis ---
REFINE_HANDSHAKE_ITERATIONS = 10
SLSQP_CENTER_MAXITER = 25
CONSTRAINT_SLACK = 0.999

def get_seed(seed_val):
    rng = np.random.default_rng(seed_val)
    seed_type = seed_val % 3
    if seed_type == 0:
        grid = np.stack(np.meshgrid(np.linspace(0.1,0.9,6), np.linspace(0.1,0.9,6)),-1).reshape(-1,2)[:N_CIRCLES]
        return np.clip(grid + (rng.random((N_CIRCLES,2))-0.5)*0.08, 0.05, 0.95)
    elif seed_type == 1:
        points = [rng.uniform(0.1, 0.9, 2)]
        for _ in range(N_CIRCLES - 1):
            candidates = rng.uniform(0.1, 0.9, (200, 2))
            dist_sq = np.sum((candidates[:, np.newaxis, :] - np.array(points)[np.newaxis, :, :])**2, axis=-1)
            min_dist_sq = np.min(dist_sq, axis=1)
            points.append(candidates[np.argmax(min_dist_sq)])
        return np.array(points)
    else:
        rows=[5,6,5,6,5,5]; points=[]; y=0.95
        for i,c in enumerate(rows): x_s=(1.0-(c-1)*0.15)/2; [points.append([x_s+j*0.15,y]) for j in range(c)]; y-=0.15
        return np.array(points)[:N_CIRCLES]

def prospect_worker(args):
    worker_id, max_iter, _ = args
    x0 = np.hstack([get_seed(worker_id), np.full((N_CIRCLES,1),0.05)]).flatten()
    def obj(x): return -np.sum(x[2::3])
    def cons(x):
        c,r=x.reshape(N_CIRCLES,3)[:,:2],x[2::3]
        I,J=np.triu_indices(N_CIRCLES,1); d2=np.sum((c[I]-c[J])**2,1); r2=(r[I]+r[J])**2
        return np.concatenate([c[:,0]-r,1-c[:,0]-r,c[:,1]-r,1-c[:,1]-r,d2-r2])
    res=minimize(obj,x0,method='SLSQP',bounds=[(0,1)if j%3<2 else(1e-12,None)for j in range(N_CIRCLES*3)],constraints={'type':'ineq','fun':cons},options={'maxiter':max_iter,'ftol':1e-10})
    return (-res.fun, res.x) if -res.fun < 4.0 else (-1.0, None)

def refine_worker(args):
    _, _, initial_params = args
    if initial_params is None: return (-1.0, None)
    centers = initial_params.reshape(N_CIRCLES, 3)[:, :2]

    for _ in range(REFINE_HANDSHAKE_ITERATIONS):
        radii = solve_radii_lp(centers)
        if np.sum(radii) < 1e-6: break
        def cons(c_flat):
            c=c_flat.reshape(N_CIRCLES,2); r=radii*CONSTRAINT_SLACK
            I,J=np.triu_indices(N_CIRCLES,1); d2=np.sum((c[I]-c[J])**2,1); r2=(r[I]+r[J])**2
            return np.concatenate([c[:,0]-r,1-c[:,0]-r,c[:,1]-r,1-c[:,1]-r,d2-r2])
        res=minimize(lambda x:0,centers.flatten(),method='SLSQP',bounds=[(0,1)]*(N_CIRCLES*2),constraints={'type':'ineq','fun':cons},options={'maxiter':SLSQP_CENTER_MAXITER,'ftol':1e-8})
        if res.success: centers=res.x.reshape(N_CIRCLES,2)
        else: break

    final_radii = solve_radii_lp(centers)
    final_params = np.hstack([centers, final_radii[:, np.newaxis]]).flatten()
    return (np.sum(final_radii), final_params)

def construct_packing() -> tuple:
    with Pool(processes=cpu_count()) as pool:
        prospect_results = pool.map(prospect_worker, [(i, MAXITER_PROSPECT, None) for i in range(N_PROSPECT)])

    prospect_results.sort(key=lambda x: x[0], reverse=True)
    elite_params = [res[1] for res in prospect_results[:N_ELITE] if res[1] is not None]
    if not elite_params: return get_seed(0), np.full((N_CIRCLES,), 0.05)

    with Pool(processes=cpu_count()) as pool:
        refine_results = pool.map(refine_worker, [(i, 0, elite_params[i]) for i in range(len(elite_params))])

    best_score, best_params = -1, None
    for score, params in refine_results:
        if score > best_score: best_score, best_params = score, params

    if best_params is None: return get_seed(0), np.full((N_CIRCLES,), 0.05)

    centers, radii = best_params.reshape(N_CIRCLES,3)[:,:2], best_params[2::3]
    return centers, radii * (1.0 - 1e-12)
